begin;
create function pg_temp.i_id(n integer) returns uuid language sql immutable as $$select ('a1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.i_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.i_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected %',state;end$$;
create function pg_temp.i_command(n integer,j text) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.i_id(n+100),'expectedVersion',0,'entry',jsonb_build_object('id',pg_temp.i_id(n+200),'registrationId',pg_temp.i_id(95),'personId',pg_temp.i_id(n),'jersey',j,'active',true))$$;
grant execute on function pg_temp.i_id(integer),pg_temp.i_assert(boolean,text),pg_temp.i_error(text,text),pg_temp.i_command(integer,text) to anon,authenticated;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.i_id(98)),(pg_temp.i_id(99));
insert into public.admin_access(user_id) values(pg_temp.i_id(98));
insert into public.championships(id,name) values(pg_temp.i_id(90),'Import fields');
insert into public.seasons(id,championship_id,year) values(pg_temp.i_id(91),pg_temp.i_id(90),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.i_id(92),pg_temp.i_id(91),'feminino','Adulto');
insert into public.teams(id,name) values(pg_temp.i_id(94),'Fields team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.i_id(95),pg_temp.i_id(92),pg_temp.i_id(94),'Fields');
insert into public.persons(id,name) select pg_temp.i_id(n),'Atleta '||n from generate_series(50,54) n;
insert into private.athletes(person_id,sex) select pg_temp.i_id(n),'female' from generate_series(50,54) n;
update private.athletes set federation_registration='001234',birth_year=1999 where person_id=pg_temp.i_id(50);
select pg_temp.i_error($q$update private.athletes set federation_registration='001234' where person_id=pg_temp.i_id(51)$q$,'23505');
select pg_temp.i_error($q$update private.athletes set federation_registration='12345' where person_id=pg_temp.i_id(51)$q$,'23514');
select pg_temp.i_error($q$update private.athletes set birth_year=0 where person_id=pg_temp.i_id(51)$q$,'23514');
select pg_temp.i_error($q$update private.athletes set birth_date='2000-01-01' where person_id=pg_temp.i_id(50)$q$,'23514');
set local role authenticated;
set local request.jwt.claim.sub='a1000000-0000-4000-8000-000000000098';
select public.save_roster_entry(pg_temp.i_command(50,null));
select public.save_roster_entry(pg_temp.i_command(51,null));
select public.save_roster_entry(pg_temp.i_command(52,'0'));
select public.save_roster_entry(pg_temp.i_command(53,'00'));
select public.save_roster_entry(pg_temp.i_command(50,null));
select pg_temp.i_error($q$select public.save_roster_entry(pg_temp.i_command(54,'0'))$q$,'PT400');
select pg_temp.i_assert(jsonb_array_length(public.list_roster(pg_temp.i_id(95))->'items')=4,'two missing jerseys allowed, no duplicate replay');
select pg_temp.i_assert(public.list_roster(pg_temp.i_id(95))->'items'->0->>'jersey'='0' and public.list_roster(pg_temp.i_id(95))->'items'->1->>'jersey'='00','known jerseys ordered first, 0 before 00');
select pg_temp.i_assert(public.get_person(pg_temp.i_id(50))->'athlete'->>'federationRegistration'='001234','leading zero registration retained');
select pg_temp.i_assert(not ((public.get_person(pg_temp.i_id(50))->'athlete')?'birthYear') and not ((public.list_persons('Atleta 50')->'items'->0)?'birthYear'),'legacy reader not expanded with private year');
-- Explicit complete date replaces the partial private year through the existing versioned writer.
select public.save_person(jsonb_build_object('commandId',pg_temp.i_id(350),'expectedVersion',1,'disputeId',null,'confirmHomonym',false,'person',(public.get_person(pg_temp.i_id(50))-'version'-'savedAt')||jsonb_build_object('athlete',jsonb_build_object('sex','female','birthDate','2000-01-01','federationRegistration','001234'))));
select pg_temp.i_assert((select birth_date='2000-01-01' and birth_year is null from private.athletes where person_id=pg_temp.i_id(50)),'complete date supersedes partial year privately');
reset role;
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.i_assert((select count(*) from private.athletes)=0,'revocation hides partial private years');
select pg_temp.i_error('select public.save_roster_entry(pg_temp.i_command(54,null))','PT403');
reset role;
rollback;
